SET QUOTED_IDENTIFIER ON; GO   IF OBJECT_ID(N'[__EFMigrationsHistory]') IS NULL BEGIN     CREATE TABLE [__EFMigrationsHistory] (         [MigrationId] nvarchar(150) NOT NULL,         [ProductVersion] nvarchar(32) NOT NULL,         CONSTRAINT [PK___EFMigrationsHistory] PRIMARY KEY ([MigrationId])     ); END; GO  BEGIN TRANSACTION; IF NOT EXISTS (     SELECT * FROM [__EFMigrationsHistory]     WHERE [MigrationId] = N'20261005081936_InitialOperations' ) BEGIN     CREATE TABLE [Drivers] (         [Id] uniqueidentifier NOT NULL,         [DriverNumber] nvarchar(80) NOT NULL,         [Name] nvarchar(200) NOT NULL,         [MobileNumber] nvarchar(25) NULL,         [IsActive] bit NOT NULL,         [CreatedAtUtc] datetime2 NOT NULL,         [CreatedByUserId] nvarchar(max) NOT NULL,         [CreatedByName] nvarchar(max) NOT NULL,         [UpdatedAtUtc] datetime2 NULL,         [UpdatedByUserId] nvarchar(max) NULL,         [UpdatedByName] nvarchar(max) NULL,         [IsDeleted] bit NOT NULL,         [DeletedAtUtc] datetime2 NULL,         [DeletedByUserId] uniqueidentifier NULL,         [DeletedByName] nvarchar(max) NULL,         CONSTRAINT [PK_Drivers] PRIMARY KEY ([Id])     ); END;  IF NOT EXISTS (     SELECT * FROM [__EFMigrationsHistory]     WHERE [MigrationId] = N'20261005081936_InitialOperations' ) BEGIN     CREATE TABLE [Ports] (         [Id] uniqueidentifier NOT NULL,         [Name] nvarchar(160) NOT NULL,         [Code] nvarchar(20) NULL,         [IsActive] bit NOT NULL,         [CreatedAtUtc] datetime2 NOT NULL,         [CreatedByUserId] nvarchar(max) NOT NULL,         [CreatedByName] nvarchar(max) NOT NULL,         [UpdatedAtUtc] datetime2 NULL,         [UpdatedByUserId] nvarchar(max) NULL,         [UpdatedByName] nvarchar(max) NULL,         [IsDeleted] bit NOT NULL,         [DeletedAtUtc] datetime2 NULL,         [DeletedByUserId] uniqueidentifier NULL,         [DeletedByName] nvarchar(max) NULL,         CONSTRAINT [PK_Ports] PRIMARY KEY ([Id])     ); END;  IF NOT EXIST